package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class ReferenceType_getGenericSignature_TriageGen0Test {

    @Mock
    private JavaType mockReferencedType;

    @Test
    public void testGetGenericSignature_Success() {
        // Arrange
        // Since ReferenceType constructor is protected, we use the static construct method
        // We need to mock the internal behavior. However, ReferenceType's fields like _class 
        // and _referencedType are usually set via the constructor.
        // We will use a subclass or the construct method to instantiate.

        Class<?> clazz = String.class;
        ReferenceType referenceType = ReferenceType.construct(clazz, mockReferencedType, null, null);

        StringBuilder sb = new StringBuilder("start");
        String expectedSuffix = "end>";

        // Mock the behavior of the referenced type's getGenericSignature
        // The method under test calls: sb = _referencedType.getGenericSignature(sb);
        // Note: The method appends '<' before calling it.
        // So we expect the input to mockReferencedType.getGenericSignature to be "start<"
        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder argumentSb = invocation.getArgument(0);
            argumentSb.append(expectedSuffix);
            return argumentSb;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // Expected flow: 
        // 1. _classSignature (appends class info, assuming it appends nothing or specific string based on class)
        // 2. append('<')
        // 3. _referencedType.getGenericSignature(sb)
        // Given ReferenceType internal logic: _classSignature appends the class signature.
        // For a simple class like String, it usually appends "Ljava/lang/String;" or similar.
        // However, to strictly test the logic provided in the snippet:

        // We verify the sequence of calls
        verify(mockReferencedType).getGenericSignature(any(StringBuilder.class));

        // Because we cannot easily mock the private/protected _classSignature without PowerMock,
        // we focus on the observable side effects of the provided code snippet.
        // The snippet shows: sb.append('<') then returns the result of the next call.

        // Since we don't know exactly what _classSignature does without the full class source,
        // we check if the result contains the characters we know were added.
        String resultStr = result.toString();
        assert(resultStr.contains("<"));
        assert(resultStr.contains("end>"));
    }

    @Test
    public void testGetGenericSignature_VerificationOfSequence() {
        // Arrange
        ReferenceType referenceType = ReferenceType.construct(Integer.class, mockReferencedType, null, null);
        StringBuilder sb = new StringBuilder();

        when(mockReferencedType.getGenericSignature(any(StringBuilder.class))).thenAnswer(invocation -> {
            StringBuilder s = invocation.getArgument(0);
            s.append("Ref");
            return s;
        });

        // Act
        StringBuilder result = referenceType.getGenericSignature(sb);

        // Assert
        // The call stack:
        // 1. _classSignature (internal)
        // 2. sb.append('<')
        // 3. mockReferencedType.getGenericSignature(sb) -> appends "Ref"

        String resultStr = result.toString();
        // The result must contain '<' and 'Ref'
        // We check the end of the string to ensure order
        int bracketIndex = resultStr.lastIndexOf('<');
        int refIndex = resultStr.lastIndexOf("Ref");

        assert(bracketIndex != -1);
        assert(refIndex != -1);
        assert(bracketIndex < refIndex);
    }
}
